CURRENT={"Cargo.toml":[4796,"aa4cbe95e537ecccff90b00da19806f746bfbf1adf73c80ea4f484e5e59044fe"],"Cargo.lock":[90202,"b868d2529f17dfb78ba390e078eb281a98d9850e4eaa12245739fec43ec97823"],"src/mcp/runtime/request_audit.rs":[71929,"7f60461194f0687c861790ca28647504b1755ab58497dbd3084bba3915b01d85"],"src/mcp/runtime/request_archive_store.rs":[55139,"ecea2101509dd8753fe308e6245a9dcd6ad0ffbb6300bc316d83aeeb21ed439c"],"src/mcp/runtime/request_archive_store_tests.rs":[41672,"95d6ebd4a7a8eede5f254b051a8447e98735cd38a9882248228e24574c7308a7"]}
ORIGINAL={"Cargo.toml":[4325,"9d95c6f534a0a5cd1b21dde659ebe2ed02c0ba7d52d5bc792118ec32d615ff14"],"Cargo.lock":[90202,"b868d2529f17dfb78ba390e078eb281a98d9850e4eaa12245739fec43ec97823"],"src/mcp/runtime/request_audit.rs":[68414,"b5189f2923153ffa83d0b45a7cdf89873b0f17ebbe6ec1b174c05bab291d73da"],"src/mcp/runtime/request_archive_store.rs":[39570,"efecc499d8032f06230e5048dfe2daf65d74560ab171aed707c187653e511c48"],"src/mcp/runtime/request_archive_store_tests.rs":[41672,"95d6ebd4a7a8eede5f254b051a8447e98735cd38a9882248228e24574c7308a7"]}
STORE_APPEND="\n// Qualification-only forwarding to the unchanged Arc/Weak Archive registry.\npub(super) struct __HiaArchiveRegistryOriginal {\n    handles: std::collections::HashMap<u64, Archive>,\n}\nimpl __HiaArchiveRegistryOriginal {\n    pub(super) fn new() -> Self { Self { handles: Default::default() } }\n    fn registry() -> serde_json::Value {\n        let Some(mutex) = STORES.get() else {\n            return serde_json::json!({\"poisoned\":false,\"entries\":[]});\n        };\n        let poisoned=mutex.is_poisoned();\n        let guard=mutex.lock().unwrap_or_else(std::sync::PoisonError::into_inner);\n        let mut rows=guard.iter().map(|(key,value)|(*key,value.strong_count())).collect::<Vec<_>>();\n        rows.sort_by_key(|value|value.0);\n        serde_json::json!({\"poisoned\":poisoned,\"entries\":rows.into_iter().map(|(key,strong)|serde_json::json!({\"key\":key,\"strong\":strong})).collect::<Vec<_>>()})\n    }\n    fn handle(&self,id:u64)->Result<serde_json::Value> {\n        let archive=self.handles.get(&id).ok_or_else(||anyhow!(\"qualification handle absent\"))?;\n        Ok(serde_json::json!({\n            \"key\":[archive.0.root_identity[0],archive.0.root_identity[1],archive.0.legacy_identity[0],archive.0.legacy_identity[1]],\n            \"strong\":Arc::strong_count(&archive.0),\n            \"loaded\":archive.0.layout.get().is_some(),\n            \"layout\":archive.0.layout.get().map(|layout|serde_json::json!({\"archive\":layout.anchor.archive,\"shards\":layout.anchor.shards}))\n        }))\n    }\n    pub(super) fn step(&mut self,value:&serde_json::Value)->serde_json::Value {\n        let operation=value[\"operation\"].as_str().unwrap();\n        let handle=value.get(\"handle\").and_then(|v|v.as_u64()).unwrap_or(0);\n        let result=(||->Result<serde_json::Value>{\n            match operation {\n                \"open\"=>{\n                    if self.handles.contains_key(&handle){bail!(\"qualification handle already present\");}\n                    let archive=super::open_archive(std::path::Path::new(value[\"root\"].as_str().unwrap()))?;\n                    self.handles.insert(handle,archive);\n                    self.handle(handle)\n                },\n                \"clone\"=>{\n                    let target=value[\"target\"].as_u64().unwrap();\n                    if self.handles.contains_key(&target){bail!(\"qualification target already present\");}\n                    let archive=self.handles.get(&handle).ok_or_else(||anyhow!(\"qualification handle absent\"))?.try_clone()?;\n                    self.handles.insert(target,archive);self.handle(target)\n                },\n                \"drop\"=>{\n                    let dropped=self.handles.remove(&handle);\n                    let existed=dropped.is_some();drop(dropped);\n                    Ok(serde_json::json!({\"dropped\":existed}))\n                },\n                \"same\"=>{\n                    let other=value[\"other\"].as_u64().unwrap();\n                    let a=self.handles.get(&handle).ok_or_else(||anyhow!(\"qualification handle absent\"))?;\n                    let b=self.handles.get(&other).ok_or_else(||anyhow!(\"qualification handle absent\"))?;\n                    Ok(serde_json::json!({\"same\":Arc::ptr_eq(&a.0,&b.0)}))\n                },\n                \"initialize\"=>{\n                    self.handles.get(&handle).ok_or_else(||anyhow!(\"qualification handle absent\"))?.initialize_shards()?;\n                    self.handle(handle)\n                },\n                \"load\"=>{\n                    self.handles.get(&handle).ok_or_else(||anyhow!(\"qualification handle absent\"))?.load_layout()?;\n                    self.handle(handle)\n                },\n                \"fence\"=>{\n                    let archive=self.handles.get(&handle).ok_or_else(||anyhow!(\"qualification handle absent\"))?;\n                    archive.fence_at(archive.root())?;self.handle(handle)\n                },\n                \"exclusive\"=>{\n                    let archive=self.handles.get(&handle).ok_or_else(||anyhow!(\"qualification handle absent\"))?;\n                    Ok(serde_json::json!({\"exclusive\":archive.needs_exclusive_open()?}))\n                },\n                \"state\"=>self.handle(handle),\n                \"registry\"=>Ok(serde_json::json!({})),\n                _=>bail!(\"unknown qualification operation\"),\n            }\n        })();\n        let observed=Self::registry();\n        match result {\n            Ok(value)=>serde_json::json!({\"accepted\":true,\"value\":value,\"registry\":observed}),\n            Err(error)=>serde_json::json!({\"accepted\":false,\"error\":{\n                \"text\":format!(\"{error:#}\"),\n                \"io_errno\":error.downcast_ref::<std::io::Error>().and_then(std::io::Error::raw_os_error),\n                \"io_kind\":error.downcast_ref::<std::io::Error>().map(|v|format!(\"{:?}\",v.kind()))\n            },\"registry\":observed}),\n        }\n    }\n}\n"
AUDIT_APPEND="\n// Qualification-only opaque observer; original Archive methods are unchanged.\n#[doc(hidden)]\npub struct __HiaDurableArchiveRegistryOriginal(archive_store::__HiaArchiveRegistryOriginal);\nimpl __HiaDurableArchiveRegistryOriginal {\n    pub fn new()->Self{Self(archive_store::__HiaArchiveRegistryOriginal::new())}\n    pub fn step(&mut self,value:&serde_json::Value)->serde_json::Value{self.0.step(value)}\n}\n"
BIN="use std::io::{BufRead,Write};\nfn main()->std::io::Result<()> {\n let mut state=hepta_runtime::mcp::runtime::request_audit::__HiaDurableArchiveRegistryOriginal::new();\n let mut output=std::io::stdout().lock();\n for line in std::io::stdin().lock().lines() {\n  let value:serde_json::Value=serde_json::from_str(&line?).unwrap();\n  let result=state.step(&value);\n  writeln!(output,\"{}\",serde_json::to_string(&result).unwrap())?;output.flush()?;\n }\n Ok(())\n}\n"
def main():
 parser=argparse.ArgumentParser();parser.add_argument("--root",type=Path,required=True);args=parser.parse_args();root=args.root.resolve(strict=True)
 before={name:(root/name).read_bytes()for name in CURRENT}
 for name,raw in before.items():
  assert[len(raw),SHA(raw)]==CURRENT[name],name
  length,pin=ORIGINAL[name];assert SHA(raw[:length])==pin,name
 q=root/"audit_archive_registry";q.mkdir(exist_ok=False)
 for name,raw in before.items():(q/("before-"+name.replace("/","__"))).write_bytes(raw)
 (q/"oracle.rs").write_text(BIN)
 for name,raw in[("src/mcp/runtime/request_archive_store.rs",STORE_APPEND),("src/mcp/runtime/request_audit.rs",AUDIT_APPEND)]:
  with(root/name).open("ab")as f:f.write(raw.encode())
 with(root/"Cargo.toml").open("ab")as f:f.write(b'\n[[bin]]\nname = "hia-durable-archive-registry-original"\npath = "audit_archive_registry/oracle.rs"\n')
 for name,raw in before.items():assert(root/name).read_bytes().startswith(raw),name
 assert(root/"Cargo.lock").read_bytes()==before["Cargo.lock"]
 assert(root/"src/mcp/runtime/request_archive_store_tests.rs").read_bytes()==before["src/mcp/runtime/request_archive_store_tests.rs"]
 report=dict(schema="hepta.runtime.durable-archive-registry-original.v1",original_commit="abc9ecb95ee9538518ec3f36c47b881974107021",
  original=ORIGINAL,before={n:dict(bytes=len(raw),sha256=SHA(raw))for n,raw in before.items()},
  after={n:dict(bytes=len(raw),sha256=SHA(raw))for n in before for raw in[(root/n).read_bytes()]},
  original_functions_whole_bytes_preserved=True,original_test_methods_whole_bytes_preserved=True,
  graph_default_features_release_profile_unchanged=True,
  scope="Actual original Archive open/clone/drop/init/load/fence plus read-only Arc::ptr_eq/strong_count and registry Weak count inspection; no replacement registry or panic-profile changes")
 (q/"source-relation.json").write_text(json.dumps(report,sort_keys=True,indent=2)+"\n");print(json.dumps(report,sort_keys=True),flush=True)
if __name__=="__main__":main()
